#!/usr/bin/env node
/**
 * tred-dire-la-verite.mjs — le chat dit enfin POURQUOI il refuse.
 *
 * Le 5 septembre, ton quota mensuel (20/20, tarif gratuit) s'affichait comme
 * « Die Verbindung wurde unterbrochen », et le client relançait toutes les
 * 900 ms un refus définitif. Trois causes différentes, un seul message, et le
 * seul faux.
 *
 * Ce paquet :
 *   • lit le corps JSON du refus (lib/chat-error.ts)
 *   • affiche le message du serveur + un lien « Tarife ansehen » sur un quota
 *   • ne relance JAMAIS un 402, et attend la seconde exacte sur un 429
 *   • 9 tests qui partent des vraies réponses du serveur
 *
 * Vérifié ici : tsc 0, oxlint 0, bun test 115/115, vite build.
 *
 *   node tred-dire-la-verite.mjs
 */
import { writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { inflateSync } from "node:zlib";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = resolve(depart);
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const parent = dirname(d);
      if (parent === d) break;
      d = parent;
    }
  }
  return null;
}

const R = racine();
if (!R) {
  console.error("Dépôt introuvable. Lance-le depuis C:\\dev\\tred-rdm\\aerostudy-ai.");
  process.exit(1);
}
console.log("Dépôt :", R, "\n");

const PAYLOAD = "";

const LOT = JSON.parse(inflateSync(Buffer.from(PAYLOAD, "base64")).toString("utf8"));
for (const [chemin, b64] of Object.entries(LOT.ecrire)) {
  const cible = join(R, chemin);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  console.log("  écrit  ", chemin);
}

console.log("\nEnsuite :");
console.log("  git add -A");
console.log("  git commit -m \"le chat dit pourquoi il refuse, au lieu de mentir\"");
console.log("  git push");
